  const DURATION = 117.88;
  const LINES = [
    [0.8, "What if time itself had a master?", null, 2.63],
    [3.73, "In Hindu tradition, Kala Bhairava is worshipped as the Lord of Time…", "big", 7.96],
    [8.86, "the divine force beyond birth, death, and destruction.", null, 12.16],
    [13.26, "But why is Bhairava given this extraordinary title?", null, 16.29],
    [17.39, "The word Kala carries a powerful meaning.", null, 19.93],
    [21.03, "It represents time…", null, 22.41],
    [23.31, "and it also represents death.", null, 25.12],
    [26.22, "Everything in this universe is controlled by time.", null, 28.99],
    [30.09, "Kings rise…", null, 31.13],
    [32.03, "empires fall…", null, 33.04],
    [33.94, "stars are born…", null, 35.13],
    [36.03, "and entire worlds eventually disappear.", null, 38.29],
    [39.39, "Nothing can escape its passage.", null, 41.22],
    [42.32, "But Kala Bhairava represents the divine power that stands beyond these limitations.", null, 47.24],
    [48.34, "He reminds us that time waits for no one…", null, 50.64],
    [51.54, "and that every action has its consequences.", null, 54.0],
    [55.1, "In his fierce form, Bhairava destroys arrogance, ignorance, and the illusion that life will last forever.", null, 61.38],
    [62.48, "He is also worshipped as the guardian of Kashi…", null, 65.07],
    [65.97, "the sacred city where devotees seek liberation from the cycle of birth and death.", null, 70.33],
    [71.43, "His presence teaches a profound lesson.", null, 73.58],
    [74.68, "Do not waste the time you have been given.", null, 76.65],
    [77.75, "Use it to follow dharma…", null, 79.13],
    [80.03, "overcome your ego…", null, 81.32],
    [82.22, "and move closer to the truth.", null, 83.86],
    [84.96, "For everything in this universe is temporary.", null, 87.24],
    [88.34, "But the eternal reality beyond time…", null, 90.53],
    [91.43, "can never be destroyed.", null, 92.81],
    [93.91, "That is why devotees remember him as Kala Bhairava…", "title", 97.09],
    [97.99, "the Lord who governs time and reminds all beings of their ultimate destiny.", "tag", 101.81],
    [102.91, "But how did this terrifying form of Lord Shiva become the protector of devotees?", null, 107.33],
    [108.43, "And why is a dog always seen beside him?", null, 110.88],
    [111.98, "That is the mystery we will uncover in the next episode.", "tag", 114.88],
  ];
